%%Dominykas Janulevičius EDIF-25/1 2026-09-28 11:00
%2 laboratorinis darbas
%%1 Var

%%Priv Uzd
%%1
V = 5:2:34 %[output:6718ef92]
Eks = exp(V) %[output:370c689f]
Sand = V.*Eks %[output:9ef51531]
Sand = Sand(:);
disp(Sand) %[output:2cecfde6]
%%2
Amx = [pi/2, 3*i, %[output:group:5f2d8bd6] %[output:7a22df1c]
    log(2), 2*pi] %[output:group:5f2d8bd6] %[output:7a22df1c]
Bvek = [exp(11), exp(12)] %[output:54e634c5]
Amx = [Amx; Bvek] %[output:85fe6952]

Sum1 = Amx(1, 1) + Amx(1, 2) %[output:7e6f8f06]
Sum2 = Amx(2, 1) + Amx(2, 2) %[output:38926736]
Sum3 = Amx(3, 1) + Amx(3, 2) %[output:9b1b697c]
%%3
t = 0:0.001:1;
A = 5; f = 5;
o = 1.5; U1 = 3; U2 = 2;
s = A*sin(2*pi*f*t);
n = o*randn(size(t));

sWN = s + n;
plot(t, sWN); %[output:5b6decaf]
xlabel('Time (s)'); ylabel('Amplitude'); %[output:5b6decaf]

a = sWN(sWN > U1) %[output:9346b03f]
sf = sWN;
sf(abs(sf) < U2) = 0;

LenS = length(sWN) %[output:77f615d1]
LenF = length(a) %[output:8d18f179]
Umax = max(sf) %[output:1b3c7537]
Umin = min(sf) %[output:623ca048]

plot(t, sf) %[output:6f0c9548]

%%Pap uzd
%%1
Avek = input('iveskite 12 elem. ');
Bvek2 = [Avek(10:end), Avek(1:end-3)];
disp(Bvek2) %[output:7d69a0b3]

